// TH18 v1.00a Extra (stage07) wave: MainSub04 + Cir02/Cir03/Cir04.
// Source: st07.ecl.txt:1254-1288 schedule; 100-204 unit bodies and emitters.
// The three groups of ten pairs are one combined formation; group starts
// (source-relative) are 0/400/800 and the schedule lasts 1000 frames.

const TH18_RICE: int = 480;       // source etSprite type 8, color 10
const RICE_COLOR: int = 10;

const TIME_LIMIT: int = 2580;     // 120 opening buffer + 2400 source estimate
const OPENING_BUFFER: int = 120;

const CIR02_Y0: int = 96;         // %A = 96, +20 per pair
const CIR02_Y_STEP: int = 20;
const CIR03_Y: int = 480;
const CIR04_Y: int = -32;

const CIR02_SHOTS: int = 200;     // Cir02_at: $A = 200, etOn every 10 frames
const CIR03_SHOTS: int = 40;      // Cir03_at: $A = 40 (Cir04 calls Cir03_at)

// Cir02_at/Cir03_at/Cir04 EX chain:
//   ANIM a=1  -> position -= 4 * velocity (handled at fire position below)
//   WAIT a=120 (cursor only, bullet keeps flying at 0.5)
//   VELTIME a=120, r=1.5, s=current angle -> scalar speed 0.5 -> 1.5
xformdef CIR_RICE {
    @120 add_speed(0fx);
    step_speed(1.5fx, 120 + 65536 * EASE_LINEAR);
}

// Cir02_at / Cir03_at firing helper.  etAim(0,0), etCount(0,1,1),
// etAngle(0,0,10deg): one aimed bullet, no fan offset (delta is unused for N=1).
// etSpeed(0,0.5,1.0) with layers=1 takes the first endpoint 0.5.
async sub rice_fire(shots: int) {
    for i in 0..shots {
        var a: angle = aim_player();
        // ANIM a=1: position -= 4 * velocity; velocity is 0.5 along a.
        var dx: fx = 2fx * cos(a);
        var dy: fx = 2fx * sin(a);
        _ = fire(TH18_RICE, RICE_COLOR,
                 $self_x - dx, $self_y - dy,
                 0.5fx, a, CIR_RICE, none);
        wait(10);
    }
}

// Common Cir02/Cir03/Cir04 body: setHurtbox(28,28) -> r14,
// setHitbox(16,16) -> r8, ordinary circular branch. The training shell
// keeps the true enemies invulnerable but preserves this body radius.
// dir is the horizontal-mirror-resolved source moveVel angle.
async sub cir_body(dir: angle, shots: int) {
    set_invuln(65535);
    set_hurtbox(14fx);
    set_hitbox(8fx);
    spawn rice_fire(shots);
    move_vel(0, dir, 1.0fx, EASE_LINEAR);
    // Source main loop after the async call: wait(1000) around a @0 jump.
    loop { wait(1000); }
}

async sub pattern() {
    wait(OPENING_BUFFER);

    // MainSub04 first group: Cir02 pairs at x=-224/+224, y=96..276.
    // Mirrored child gets the horizontally mirrored moveVel angle 0 -> 180deg.
    for i1 in 0..10 {
        var y: int = CIR02_Y0 + i1 * CIR02_Y_STEP;
        _ = spawn_enemy(-224fx, y as fx, 240, 0, 1000, 0, cir_body(0deg, CIR02_SHOTS));
        _ = spawn_enemy(224fx, y as fx, 240, 0, 1000, 0, cir_body(180deg, CIR02_SHOTS));
        wait(20);
    }
    wait(200);

    // Second group at source-relative 400: Cir03 pairs at x=-170/+170, y=480.
    // moveVel(-pi/2,1) is vertical; horizontal mirror leaves it unchanged.
    for i2 in 0..10 {
        _ = spawn_enemy(-170fx, CIR03_Y as fx, 240, 0, 1000, 0, cir_body(-90deg, CIR03_SHOTS));
        _ = spawn_enemy(170fx, CIR03_Y as fx, 240, 0, 1000, 0, cir_body(-90deg, CIR03_SHOTS));
        wait(20);
    }
    wait(200);

    // Third group at source-relative 800: Cir04 pairs at x=-80/+80, y=-32.
    // Cir04 calls Cir03_at (40 shots); moveVel(pi/2,1) is vertical.
    for i3 in 0..10 {
        _ = spawn_enemy(-80fx, CIR04_Y as fx, 240, 0, 1000, 0, cir_body(90deg, CIR03_SHOTS));
        _ = spawn_enemy(80fx, CIR04_Y as fx, 240, 0, 1000, 0, cir_body(90deg, CIR03_SHOTS));
        wait(20);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
